import{describe,it,expect,beforeEach}from"vitest";import{CrowdDensityEngine}from"../../frontend/js-modules/crowd-density-engine.js";const destinations=[{id:"agra",name:"Taj Mahal, Agra",state:"Uttar Pradesh",popularity:10,siteType:"monument",peakMonths:[10,11,12,1,2,3]},{id:"jaipur",name:"Amber Fort, Jaipur",state:"Rajasthan",popularity:9,siteType:"monument",peakMonths:[10,11,12,1,2,3]},{id:"goa",name:"Baga Beach, Goa",state:"Goa",popularity:9,siteType:"beach",peakMonths:[11,12,1]}],holidays=[{name:"Diwali",date:"2026-11-08",scope:"national",impact:1},{name:"Ganesh Chaturthi",date:"2026-09-14",scope:"regional",states:["Maharashtra"],impact:1}],nearbyAlternatives={agra:[{id:"jaipur",distanceKm:240}]};function buildEngine(){return new CrowdDensityEngine({destinations:destinations,holidays:holidays,nearbyAlternatives:nearbyAlternatives})}describe("CrowdDensityEngine.predictCrowdLevel",()=>{let e;beforeEach(()=>{e=buildEngine()}),it("returns null for an unknown destination",()=>{expect(e.predictCrowdLevel("atlantis","2026-07-27")).toBeNull()}),it("returns null for an invalid date",()=>{expect(e.predictCrowdLevel("agra","not-a-date")).toBeNull()}),it("scores a weekday in the off-season lower than a weekend holiday in-season",()=>{const t=e.predictCrowdLevel("agra","2026-11-08"),a=e.predictCrowdLevel("agra","2026-07-14");expect(t.score).toBeGreaterThan(a.score),expect(t.level.key).toBe("high"),expect(a.level.key).not.toBe("high")}),it("applies regional holidays only within the matching state",()=>{const e=new CrowdDensityEngine({destinations:[...destinations,{id:"mumbai",name:"Gateway of India",state:"Maharashtra",popularity:8,siteType:"monument",peakMonths:[]}],holidays:holidays,nearbyAlternatives:nearbyAlternatives}),t=e.predictCrowdLevel("mumbai","2026-09-14"),a=e.predictCrowdLevel("agra","2026-09-14");expect(t.factors.holiday).toBeGreaterThan(0),expect(a.factors.holiday).toBe(0)}),it("keeps the score within 0-100 bounds",()=>{const t=e.predictCrowdLevel("agra","2026-11-08",{weather:{condition:"clear"}});expect(t.score).toBeGreaterThanOrEqual(0),expect(t.score).toBeLessThanOrEqual(100)}),it("applies a negative weather factor for rain",()=>{const t=e.predictCrowdLevel("agra","2026-07-14",{weather:{condition:"clear"}}),a=e.predictCrowdLevel("agra","2026-07-14",{weather:{condition:"rain"}});expect(a.score).toBeLessThan(t.score)})}),describe("CrowdDensityEngine.levelForScore",()=>{it("classifies scores into low/moderate/high buckets",()=>{expect(CrowdDensityEngine.levelForScore(10).key).toBe("low"),expect(CrowdDensityEngine.levelForScore(50).key).toBe("moderate"),expect(CrowdDensityEngine.levelForScore(90).key).toBe("high")})}),describe("CrowdDensityEngine.getBestVisitingHours",()=>{it("returns quiet hours sorted chronologically and the busiest hour",()=>{const e=buildEngine().getBestVisitingHours("agra","2026-07-14",{limit:3});expect(e.recommendedHours).toHaveLength(3);const t=e.recommendedHours.map(e=>e.hour);expect(t).toEqual([...t].sort((e,t)=>e-t)),expect(e.busiestHour.relativeCrowd).toBe(100)}),it("returns null for an unknown destination",()=>{const e=buildEngine();expect(e.getBestVisitingHours("atlantis","2026-07-14")).toBeNull()})}),describe("CrowdDensityEngine.getForecast",()=>{it("builds a forecast of the requested length",()=>{const e=buildEngine().getForecast("agra","2026-07-13",5);expect(e).toHaveLength(5),expect(e[0].date).toBe("2026-07-13"),expect(e[4].date).toBe("2026-07-17")})}),describe("CrowdDensityEngine.suggestAlternatives",()=>{it("only suggests alternatives predicted less crowded than the primary destination",()=>{const e=buildEngine(),t=e.suggestAlternatives("agra","2026-11-08");for(const a of t)expect(a.prediction.score).toBeLessThan(e.predictCrowdLevel("agra","2026-11-08").score)}),it("returns an empty array when there are no configured alternatives",()=>{const e=buildEngine();expect(e.suggestAlternatives("goa","2026-11-08")).toEqual([])})}),describe("CrowdDensityEngine.optimizeItinerary",()=>{it("leaves non-high stops untouched",()=>{const e=buildEngine().optimizeItinerary([{destinationId:"agra",date:"2026-07-14"}]);expect(e[0].suggestion).toBeNull()}),it("suggests a lower-scoring nearby date for a predicted-high stop",()=>{const e=buildEngine().optimizeItinerary([{destinationId:"agra",date:"2026-11-08"}],{flexibilityDays:2});expect(e[0].prediction.level.key).toBe("high"),e[0].suggestion&&expect(e[0].suggestion.predictedScore).toBeLessThan(e[0].prediction.score)})}),describe("CrowdDensityEngine feedback",()=>{it("nudges future predictions toward reported actual crowd levels",()=>{const e=buildEngine(),t=e.predictCrowdLevel("agra","2026-07-14").score;e.recordFeedback("agra",t,t+20);const a=e.predictCrowdLevel("agra","2026-07-14").score;expect(a).toBeGreaterThan(t)}),it("clamps the adjustment to +/-15",()=>{const e=buildEngine();for(let t=0;t<20;t++)e.recordFeedback("agra",0,100,{weight:1});expect(e.getFeedbackAdjustment("agra")).toBeLessThanOrEqual(15)}),it("restores persisted adjustments via loadFeedbackAdjustments",()=>{const e=buildEngine();e.loadFeedbackAdjustments({agra:12}),expect(e.getFeedbackAdjustment("agra")).toBe(12)})});